from collections import deque
def solve(I):
    H,W=len(I),len(I[0]); bg=max(set(x for r in I for x in r), key=lambda c: sum(r.count(c) for r in I))
    colors=[c for c in set(x for r in I for x in r) if c!=bg]
    assert len(colors)==1,(colors,I)
    col=colors[0]
    seen=[[False]*W for _ in range(H)]
    q=deque()
    for i in range(H):
        for j in (0,W-1):
            if I[i][j]==bg: q.append((i,j)); seen[i][j]=True
    for j in range(W):
        for i in (0,H-1):
            if I[i][j]==bg: q.append((i,j)); seen[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and I[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    out=[r[:] for r in I]
    for i in range(H):
        for j in range(W):
            if I[i][j]==bg and not seen[i][j]:
                out[i][j]=4
    return out
O=solve(G['Demo pair 1 input'])
